        [[5.6,11.6],[11.2,11.4],[11.6,17],[6,17.2],[17,11.4],[22.4,11.6],[22,17.2],[16.4,17]].forEach(([x,y])=>{ e.ell(x,y,0.6,0.6,STEEL[4]); e.rect(x-0.4,y-0.4,0.4,0.4,'#ffffff'); });
