    if(P.impact>=0.5) parts.push({noShade:true,smear:true,draw:(c,u)=>{ const p=pen(c,u); p.id(); star(p,P.kick?MOVESET.kickTip(sk,P):lp(sk.wrF,P.aFe+P.bat-sk.ro,T.len),P.impact>=2?14:10,M.smear[1],M.smear[0]); }});
