    p.F(M.shirt[1]); p.poly([[-31,-6],[-10,-8],[-11,-2],[-30,-1]]);
    p.F(M.shirt[2]); p.poly([[8,-8],[26,-8],[24,0],[20,-3],[16,6],[12,-2]]);
