    const top=[]; for(let k=0;k<=6;k++){ const q=sk.T(lerp({x:-44*wd,y:0},{x:50*wd,y:0},k/6).x, wy+8-Math.sin(k/6*PI)*3); top.push([q.x,q.y]); }
