    p.F(M.hair[3]); p.cap(P2(0,0),P2(0,-RW+6),3,1.6); p.cap(P2(0,0),P2(S(wob)*(RW-3),-C(wob)*(RW-3)),1.8,1); p.circle(P2(0,0),1.8);
    p.F(D[3]); p.rect(-0.5,-0.5,1,1);
