    fold(p,J,[[t.L*0.68,-12],[t.L*0.76,-6],[t.L*0.72,0]],1.3); fold(p,J,[[t.L*0.46,10],[t.L*0.62,11]],1.2);
    p.F(J[0]); p.cap(P2(t.L*0.15,-11),P2(t.L*0.5,-12),1.2,1);
