  const PCOL=['pA','pC','pB'];
  function fanAngles(n,spread,P){ const o=[]; for(let k=0;k<n;k++){ const u=k/(n-1)-0.5; o.push([u,180+u*spread*P.fan-(P.lean)+P.wind*22*(0.5+Math.abs(u))]); } return o; }
