      p.F(Q[1]); p.cap(P2(s0[0]-6,s0[1]+4),P2(e0[0],e0[1]),26,20); p.F(R[3]); p.cap(P2(s0[0]-8,s0[1]+8),P2(e0[0]-2,e0[1]+2),12,8);
      // sombra do controlador e das correias na farda
