      fold(p,R,[[30,-96],[20,-84],[8,-78]],1.2); fold(p,R,[[34,-78],[22,-66],[12,-62]],1.1); fold(p,R,[[-24,-10],[-12,-14],[2,-9]],1.2);
      fold(p,R,[[6,-12],[18,-16],[30,-12]],1.1); fold(p,R,[[-24,-56],[-18,-46],[-20,-34]],1); fold(p,R,[[-20,-118],[-10,-112]],1);
      // bolso com lapela
