    const t=P.turn; if(t<0.999) cv=turnCanvas(cv,t,K);
    const sc=q=>({x:q.x*K,y:q.y*K}); cv._eye=sc(sk.H(8.4,-10.4)); cv._mouth=sc(sk.H(10,-2)); cv._hand=sc(sk.wrF); cv._head=sc(sk.H(3,-13)); cv._handB=sc(sk.wrB); cv._tray=sc(sk.tc);
