      fruit:['#d8b070','#9a6a34','#5e3a1c','#2e1a0c'],
      pulp:['#fff4d8','#f0dcae','#c4a46e','#7a6040'],
      mold:['#e6f4a8','#a8c84a','#6a8a2e','#3a4a1c'],
      wood:['#ccbc9a','#8e7a5a','#5a4a36','#30261c'],
      leaf:['#acdc74','#5e9a3a','#33622a','#1a3a1e'],
