  /* ---------------- cabeça ---------------- */
  const HEAD=[[-8,-4],[-7,-12],[-2,-18],[8,-21],[18,-20.6],[27,-17],[34,-14],[40,-10.6],[44,-7],[44.6,0],[42,4.6],[35,7],[26,8],[18,9],[14,15],[8,20],[0,19],[-6,10]];
