      p.F(M.cream[0]); p.poly([[34,-3],[37,-2.6],[38,-0.6],[35.6,-0.4]]); p.F(M.cream[2]); p.poly([[30,4],[36,5.6],[41,4.4],[40,6],[35,8],[29,7]]);
      // pintas sólidas da cabeça
