    p.F(M.nose[2]); p.poly([[38,-9],[43.6,-7],[44.4,-3],[42,-1.6],[38.4,-4.6]]); p.F(M.nose[1]); p.poly([[39,-8.4],[43,-6.6],[43,-4],[40,-5]]); p.F(M.nose[0]); p.rect(40,-8,2,1);
    p.F(M.nose[3]); p.rect(42.6,-3.4,1.4,1.2);
