  function topQuad(x,G,w,h,dx,dy,f){ const c=[[x,G-h],[x+w,G-h],[x+w+dx,G-h+dy],[x+dx,G-h+dy]]; if(!f) return c; const cx=x+w/2+dx/2, cy=G-h+dy/2; return c.map(q=>[cx+(q[0]-cx)*f,cy+(q[1]-cy)*f*1.0]); }
