  for(let k=0;k<4;k++){ const lx=x+70+k*72; R(g,lx-6,yb-216,12,10,ir[2]); if(k%2){ emit(g,g=>ell(g,lx,yb-204,4,3,'#fff0c0')); glow(g,lx,yb-200,50,'#ffd890',.06,3); } else R(g,lx-4,yb-206,8,3,'#2a2030'); }
