  poly(g,[[x+w*.25,yb-h],[x+w/2,yb-h-18],[x+w*.75,yb-h]],c[2]); line(g,x+w*.25,yb-h,x+w/2,yb-h-18,wt[1],2); line(g,x+w/2,yb-h-18,x+w*.75,yb-h,wt[1],2);
