    add(X0,X1,0,(g,lo,hi)=>baia(g,Math.max(lo,X0),Math.min(hi,X1),s,{boats:true}));
    add(X0,X0+2260,1,(g,lo,hi)=>mureta(g,Math.max(lo,X0),Math.min(hi,X0+2260),HB-44,s));
