  g.ellipse(cx,hy,72,80,0,0,Math.PI*2); g.moveTo(cx-120,HH); g.lineTo(cx-60,HH-80); g.lineTo(cx+60,HH-80); g.lineTo(cx+120,HH); g.closePath();
