  if(t==='barril'){ w=130; [c,g]=mk(w,HH); fgBarril(g,w); return fgCache[t]={c,w}; }
  if(t==='paneiro'){ w=240; [c,g]=mk(w,HH); fgPaneiros(g,w); return fgCache[t]={c,w}; }
