  for(let k=0;k<=anc;k++){ const px=Math.round(x+k*w/anc); R(g,px-3,eave-6,6,HB-eave+6,ir[4]); R(g,px-2,eave-6,2,HB-eave+6,ir[1]); line(g,px,eave-4,px+(k<anc/2?-30:30),HB,ir[3]); }
