    archF(g,ox-rU-6,cU-6,(rU+6)*2,rU+6,c[3]); archF(g,ox-rU-5,cU-5,(rU+5)*2,rU+5,c[1]); archF(g,ox-rU-2,cU-2,(rU+2)*2,rU+2,c[2]);
    R(g,ox-5,cL-9,10,10,c[1]); R(g,ox-5,cL-9,10,1,c[0]); R(g,ox+3,cL-8,2,9,c[3]); R(g,ox-4,cU-7,8,8,c[1]); R(g,ox-4,cU-7,8,1,c[0]); R(g,ox+2,cU-6,2,7,c[3]);
    for(const [sp,r] of [[sL,rL],[sU,rU]]){ R(g,ox-r-8,sp-4,r*2+16,5,c[1]); R(g,ox-r-8,sp-4,r*2+16,1,c[0]); R(g,ox-r-8,sp+1,r*2+16,2,c[4]); }
