  const skyline=(a,b,sd)=>{ for(let x=a,i=0;x<b-80;i++){ const w=110+Math.round(hsh(sd+i*3.1)*120), xx=x, v=hsh(sd+i*7.7); if(v<.5) add(xx,xx+w,0,g=>predioModerno(g,xx,w,sd+i)); else if(v<.78) add(xx,xx+w,0,g=>predioModular(g,xx,w,30+Math.round(hsh(sd+i)*80),sd+i)); else tel(xx,xx+w); x+=w+Math.round(hsh(sd+i*5)*40); } };
