function farStrip(mode,lvl){ const k='f'+lvl+mode; if(stripCache[k]) return stripCache[k]; const P=SKYP[mode], W0=lvl===1?2880:2400, [c,g]=mk(W0,HB);
  const col=lvl===1?P.f1:P.f2, wc=lvl===1?P.f1w:P.f2w, cc=rmp(col);
  if(lvl===1){ // serra e morros cariocas: Pão de Açúcar, Urca, pico do Corcovado (sem a estátua), Dois Irmãos
    const pk=[[260,120,150,'pao'],[120,70,180,'dome'],[560,26,130,'dome'],[1040,150,90,'pico'],[1500,70,200,'dome'],[1880,96,110,'pico'],[2000,88,90,'pico'],[2460,60,220,'dome'],[2760,40,160,'dome']];
    const hy=x=>{ let y=HZ-6+Math.sin(x/W0*Math.PI*6)*4; for(const [px,h,r,t] of pk){ for(const o of [0,W0,-W0]){ const u=Math.abs(x-px-o)/r; if(u>=1) continue; const f=t==='pao'?Math.pow(1-u*u,.45):t==='pico'?Math.pow(1-u,1.6):Math.pow(1-u*u,1.2); y=Math.min(y,HZ-6-h*f); } } return y; };
    for(let x=0;x<W0;x+=2){ const y=Math.round(hy(x)); R(g,x,y,2,HB-y,cc[2]); R(g,x,y,2,1,cc[1]); if(hsh(x*.31)>.5) R(g,x,y+1,2,2,cc[1]); R(g,x+1,y+3,1,HB-y,mix(cc[2],cc[3],.4)); }
    sag(g,140,HZ-72,260,HZ-118,6,cc[4],1);
    if(wc) for(let i=0;i<W0/6;i++){ const x=i*6+hsh(i*3.3)*4, y=HZ-4-hsh(i*7.1)*16; if(hsh(i*1.7)>.55){ g.fillStyle=wc; g.fillRect(x,y,1,1); } } }
  else { // o Centro: torres de escritório e o morro com casinhas acesas
    const hy=x=>HZ-10+Math.sin(x/W0*Math.PI*4+2)*10;
    for(let i=0;i<W0/30;i++){ const x=i*30+Math.round(hsh(i*3.1)*12), v=hsh(i*7.7); if(v<.3||x>W0-40) continue; const w=16+Math.round(hsh(i*5.3)*20), h=40+Math.round(Math.pow(hsh(i*2.9),1.4)*120), y=HZ-h;
      R(g,x,y,w,HB-y,cc[2]); R(g,x,y,w,1,cc[1]); R(g,x+w-3,y,3,HB-y,cc[3]); if(v>.86){ R(g,x+w/2-1,y-12,2,12,cc[2]); g.fillStyle='#ff4a3a'; g.fillRect(x+w/2-1,y-13,2,2); }
      if(wc) for(let yy=y+4;yy<HZ+10;yy+=6) for(let xx=x+3;xx<x+w-4;xx+=5) if(hsh(xx*1.3+yy*.7)>.84){ g.fillStyle=wc; g.fillRect(xx,yy,2,2); } }
    for(let x=0;x<W0;x+=2){ const y=Math.round(hy(x)+30+Math.sin(x*.013)*8); R(g,x,y,2,HB-y,cc[3]); }
    for(let i=0;i<W0/12;i++){ const x=i*12+hsh(i*3.3)*6, y=hy(x)+34+hsh(i*5.1)*40; R(g,x,y,9,6,cc[2]); R(g,x,y,9,1,cc[1]); if(wc&&hsh(i*9.1)>.5){ g.fillStyle=wc; g.fillRect(x+2,y+2,2,2); } } }
  return stripCache[k]=c; }

